import xml.etree.ElementTree as ET
import csv

def task_func(xml_content, output_csv_path):
    root = ET.fromstring(xml_content)

    rows = list(root) if len(root) > 0 else [root]

    def flatten(element, prefix=""):
        data = {}

        for key, value in element.attrib.items():
            data[f"{prefix}@{key}" if prefix else f"@{key}"] = value

        children = list(element)
        text = (element.text or "").strip()

        if not children:
            if prefix:
                data[prefix] = text
            else:
                data[element.tag] = text
            return data

        if text and prefix:
            data[prefix] = text

        for child in children:
            child_prefix = f"{prefix}.{child.tag}" if prefix else child.tag
            child_data = flatten(child, child_prefix)
            for key, value in child_data.items():
                if key in data:
                    data[key] = f"{data[key]};{value}"
                else:
                    data[key] = value

        return data

    flattened_rows = [flatten(row) for row in rows]

    headers = []
    seen = set()
    for row in flattened_rows:
        for key in row:
            if key not in seen:
                seen.add(key)
                headers.append(key)

    with open(output_csv_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.DictWriter(csv_file, fieldnames=headers)
        writer.writeheader()
        writer.writerows(flattened_rows)
